const cfg = $('Settings').first().json;
const store = String(cfg.competitor_store || '').trim();

// single-item input: one fetch node, one store, one HTTP response. There is no
// second item here to drop - the whole catalogue arrives inside this one body.
let payload = $input.first().json;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) { payload = {}; }
} else if (typeof payload.data === 'string') {
  try { payload = JSON.parse(payload.data); } catch (e) { payload = {}; }
}

// A store that is not on Shopify answers 200 with a rendered page. Parsed
// naively that is indistinguishable from an empty catalogue, which would read
// as "nothing new" every single run.
if (!payload || !Array.isArray(payload.products)) {
  throw new Error(
    store + ' did not return a Shopify catalogue. Check the domain is a Shopify ' +
    'store and that ' + store + '/products.json opens in a browser.'
  );
}

const out = [];
for (const p of payload.products) {
  const variants = Array.isArray(p.variants) ? p.variants : [];
  const prices = variants
    .map((v) => Number(v.price))
    .filter((x) => !isNaN(x) && x > 0);
  if (!prices.length) continue;

  const inStock = variants.some((v) => v.available);
  out.push({
    side: 'theirs',
    store,
    handle: p.handle || '',
    title: String(p.title || '').trim(),
    product_type: String(p.product_type || '').split('>').pop().trim() || 'Uncategorised',
    vendor: p.vendor || '',
    price: Math.min.apply(null, prices),
    price_max: Math.max.apply(null, prices),
    variants: variants.length,
    in_stock: inStock,
    published_at: p.published_at || '',
    url: 'https://' + store.replace(/^https?:\/\//, '').replace(/\/$/, '') + '/products/' + (p.handle || ''),
  });
}

if (!out.length) {
  throw new Error(store + ' returned a Shopify catalogue with no priced products.');
}

return out.map((x) => ({ json: x }));

const cfg = $('Settings').first().json;
const store = String(cfg.your_store || '').trim();

// single-item input: one fetch node, one store, one HTTP response. There is no
// second item here to drop - the whole catalogue arrives inside this one body.
let payload = $input.first().json;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) { payload = {}; }
} else if (typeof payload.data === 'string') {
  try { payload = JSON.parse(payload.data); } catch (e) { payload = {}; }
}

// A store that is not on Shopify answers 200 with a rendered page. Parsed
// naively that is indistinguishable from an empty catalogue, which would read
// as "nothing new" every single run.
if (!payload || !Array.isArray(payload.products)) {
  throw new Error(
    store + ' did not return a Shopify catalogue. Check the domain is a Shopify ' +
    'store and that ' + store + '/products.json opens in a browser.'
  );
}

const out = [];
for (const p of payload.products) {
  const variants = Array.isArray(p.variants) ? p.variants : [];
  const prices = variants
    .map((v) => Number(v.price))
    .filter((x) => !isNaN(x) && x > 0);
  if (!prices.length) continue;

  const inStock = variants.some((v) => v.available);
  out.push({
    side: 'yours',
    store,
    handle: p.handle || '',
    title: String(p.title || '').trim(),
    product_type: String(p.product_type || '').split('>').pop().trim() || 'Uncategorised',
    vendor: p.vendor || '',
    price: Math.min.apply(null, prices),
    price_max: Math.max.apply(null, prices),
    variants: variants.length,
    in_stock: inStock,
    published_at: p.published_at || '',
    url: 'https://' + store.replace(/^https?:\/\//, '').replace(/\/$/, '') + '/products/' + (p.handle || ''),
  });
}

if (!out.length) {
  throw new Error(store + ' returned a Shopify catalogue with no priced products.');
}

return out.map((x) => ({ json: x }));

// Reach back to both branches by name. The Merge above is what makes that safe:
// the two fetches are independent branches, and without a barrier this node
// could run before the second one has produced anything.
const cfg = $('Settings').first().json;
const theirs = $('Read Their Products').all().map((x) => x.json);
const yours = $('Read Your Products').all().map((x) => x.json);

// Your price range per product type. Comparing like for like by type is
// something both stores actually publish; matching product titles across two
// catalogues would be a guess dressed up as a fact.
const yourRange = {};
for (const p of yours) {
  const k = p.product_type.toLowerCase();
  if (!yourRange[k]) yourRange[k] = { lo: p.price, hi: p.price, n: 0 };
  yourRange[k].lo = Math.min(yourRange[k].lo, p.price);
  yourRange[k].hi = Math.max(yourRange[k].hi, p.price);
  yourRange[k].n += 1;
}

// The fallback band: your entire catalogue, low to high.
const allPrices = yours.map((p) => p.price).filter((x) => x > 0);
const wholeCatalogue = {
  lo: allPrices.length ? Math.min.apply(null, allPrices) : 0,
  hi: allPrices.length ? Math.max.apply(null, allPrices) : 0,
  n: allPrices.length,
};

const newDays = Number(cfg.new_within_days || 30);
const cutoff = Date.now() - newDays * 86400000;

const rows = theirs.map((p) => {
  const published = Date.parse(p.published_at || '') || 0;
  const k = p.product_type.toLowerCase();
  const mine = yourRange[k];

  // Prefer the like-for-like comparison, but never return nothing. Two stores
  // almost never spell product_type the same way - Gymshark files a top as
  // `crop_top` where another store says `T-Shirts` - so a type match is a bonus,
  // not something to depend on. Without one, compare against the whole
  // catalogue, which is always there and still answers the real question:
  // where does their pricing sit against ours?
  const band = mine || wholeCatalogue;
  const scope = mine ? ('your ' + p.product_type + ' range') : 'your whole catalogue';

  let position;
  let gap_pct = 0;
  if (p.price < band.lo) {
    position = 'undercuts ' + scope;
    gap_pct = Math.round(((band.lo - p.price) / band.lo) * 100);
  } else if (p.price > band.hi) {
    position = 'above ' + scope;
    gap_pct = Math.round(((p.price - band.hi) / band.hi) * 100);
  } else {
    position = 'inside ' + scope;
  }

  return Object.assign({}, p, {
    // Store and handle together - two stores can share a handle.
    product_key: p.store + '|' + p.handle,
    is_recent: published >= cutoff,
    position,
    gap_pct,
    your_type_count: mine ? mine.n : 0,
  });
});

// Their newest first: a launch from this week matters more than one from last month.
rows.sort((a, b) => (Date.parse(b.published_at || '') || 0) - (Date.parse(a.published_at || '') || 0));

const cap = Number(cfg.max_products_reported || 40);
return rows.slice(0, cap).map((r) => ({ json: r }));

// Read the products by name, not from this node's input. The Data Table insert
// above emits the rows it wrote - product_key and first_seen - so $input here
// carries none of the fields the email needs.
const cfg = $('Settings').first().json;

// Do not ask whether the quiet branch ran. Both branches lead here, and
// referencing a node on the path that did not execute throws outright:
// "Node 'Nothing New Today' hasn't been executed". Whether there is anything
// to report is already answerable from the data itself.
const rows = $('Only Products Never Seen').all()
  .map((x) => x.json)
  .filter((r) => r && r.product_key);

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const money = (n) => (cfg.currency_symbol || '$') + Number(n).toFixed(2);

if (!rows.length) {
  return [{
    json: {
      subject: 'No new products at ' + cfg.competitor_store,
      html:
        '<p>Nothing new on <b>' + esc(cfg.competitor_store) + '</b> since the last check.</p>' +
        '<p style="color:#666;font-size:12px">Every product on their first page has been reported before.</p>',
      count: 0,
    },
  }];
}

const soldOut = rows.filter((r) => !r.in_stock);
const undercut = rows.filter((r) => r.gap_pct !== null && r.position.indexOf('undercuts') === 0);

let html =
  '<p><b>' + rows.length + '</b> product(s) appeared on <b>' + esc(cfg.competitor_store) +
  '</b> that this workflow has not reported before.</p>';

if (soldOut.length) {
  html += '<p><b>' + soldOut.length + '</b> of them are already sold out - ' +
          'the clearest demand signal on the page.</p>';
}
if (undercut.length) {
  html += '<p><b>' + undercut.length + '</b> undercut your range for the same product type.</p>';
}

html += '<table cellpadding="6" cellspacing="0" border="0" style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:13px">' +
        '<tr style="background:#f4f4f4;text-align:left">' +
        '<th>Product</th><th>Type</th><th>Price</th><th>Stock</th><th>Against your range</th></tr>';

for (const r of rows) {
  html +=
    '<tr style="border-bottom:1px solid #eee">' +
    '<td><a href="' + esc(r.url) + '">' + esc(r.title) + '</a>' +
    (r.is_recent ? ' <span style="color:#0a7">new</span>' : '') + '</td>' +
    '<td>' + esc(r.product_type) + '</td>' +
    '<td>' + money(r.price) + (r.price_max > r.price ? '&ndash;' + money(r.price_max) : '') + '</td>' +
    '<td>' + (r.in_stock ? 'in stock' : '<b>sold out</b>') + '</td>' +
    '<td>' + esc(r.position) + (r.gap_pct ? ' (' + r.gap_pct + '%)' : '') + '</td>' +
    '</tr>';
}
html += '</table>';
html += '<p style="color:#666;font-size:12px">One page of up to 250 products per store. ' +
        'Prices compared by product type, not by matching product names.</p>';

return [{
  json: {
    subject: rows.length + ' new product(s) at ' + cfg.competitor_store,
    html,
    count: rows.length,
  },
}];
